syntax = "proto3";

package hasher;

option go_package = "backend_server/internal/proto/hasher";

service HasherTrainingService {
    rpc ExportSecurityData(ExportRequest) returns (stream EncryptedChunk);
    rpc TriggerTraining(TrainingRequest) returns (TrainingResponse);
    rpc GetTrainingStatus(TrainingStatusRequest) returns (TrainingStatusResponse);
    rpc GetUserRules(RulesRequest) returns (RulesResponse);
    rpc ValidateAction(ActionRequest) returns (ActionResponse);
    rpc StreamActivity(StreamActivityRequest) returns (stream ActivityEvent);
}

message ExportRequest {
    string org_id = 1;
    string user_id = 2;
    DataType data_type = 3;
    bool encrypted = 4;

package headless

// Request/response types for headless API

// ErrorResponse represents an error response
type ErrorResponse struct {
	Error   string `json:"error"`
	Code    int    `json:"code"`
	Message string `json:"message,omitempty"`
}

// StatusResponse represents the status response
type StatusResponse struct {
	DriverRunning bool   `json:"driver_running"`
	ServerReady   bool   `json:"server_ready"`
	DeviceIP      string `json:"device_ip,omitempty"`
	DeviceType    string `json:"device_type,omitempty"`
	Uptime        string `json:"uptime"`
}

